<?php

use App\Enums\TeamRole;
use App\Models\ImportBatch;
use App\Models\Product;
use App\Models\Team;
use App\Models\User;
use App\Services\Inventory\SkuGenerator;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;

/**
 * Category-based SKUs (BRK-000001, LGT-000001, …): generated by the server, sequential per
 * category, unique, kept when a file provides one, and never changed afterwards.
 */
beforeEach(function () {
    Storage::fake('local');
    $this->team = Team::factory()->create(['slug' => 'sku-team']);
    $this->user = User::factory()->create(['role' => 'admin', 'current_team_id' => $this->team->id, 'password_changed_at' => now()]);
    $this->team->members()->attach($this->user, ['role' => TeamRole::Owner->value]);
    $this->cookies = createTrustedDeviceFor($this->user)['cookies'];
    $this->url = "/{$this->team->slug}";
});

function skuAs($t)
{
    return $t->actingAs($t->user)->withCookies($t->cookies);
}

function skuProduct($t, string $name, string $category, array $extra = []): array
{
    return ['name' => $name, 'category' => $category, 'unit' => 'pcs', 'price' => 100, 'cost_price' => 70, 'stock' => 0, 'reorder_level' => 5, 'reorder_quantity' => 10] + $extra;
}

it('maps categories to 3-letter prefixes', function (string $category, string $prefix) {
    expect(SkuGenerator::prefix($category))->toBe($prefix);
})->with([
    ['Breakers', 'BRK'], ['Lighting', 'LGT'], ['Wiring', 'WIR'], ['Controls', 'CTL'], ['Tools', 'TLS'], ['General', 'GEN'],
    ['  lighting ', 'LGT'], ['Conduits', 'CND'], ['Panel Boards', 'PNL'], ['', 'GEN'], ['Ice', 'ICE'], ['PV', 'PVX'],
]);

it('generates sequential SKUs per category when staff create products, ignoring any typed SKU', function () {
    expect(skuAs($this)->withCredentials()->getJson("{$this->url}/inventory/next-sku?category=Breakers")->assertOk()->json('sku'))->toBe('BRK-000001');

    skuAs($this)->post("{$this->url}/inventory/products", skuProduct($this, 'Breaker 20A', 'Breakers', ['sku' => 'HACKED-1']))->assertSessionHasNoErrors()
        ->assertSessionHas('success', fn ($m) => str_contains($m, 'BRK-000001'));
    skuAs($this)->post("{$this->url}/inventory/products", skuProduct($this, 'Breaker 30A', 'Breakers'))->assertSessionHasNoErrors();
    skuAs($this)->post("{$this->url}/inventory/products", skuProduct($this, 'LED Bulb 9W', 'Lighting'))->assertSessionHasNoErrors();
    skuAs($this)->post("{$this->url}/inventory/products", skuProduct($this, 'THHN 3.5mm', 'Wiring'))->assertSessionHasNoErrors();

    expect(Product::orderBy('id')->pluck('sku')->all())->toBe(['BRK-000001', 'BRK-000002', 'LGT-000001', 'WIR-000001'])
        ->and(skuAs($this)->withCredentials()->getJson("{$this->url}/inventory/next-sku?category=Breakers")->json('sku'))->toBe('BRK-000003');
});

it('keeps the SKU when the product is edited, even if its category changes', function () {
    skuAs($this)->post("{$this->url}/inventory/products", skuProduct($this, 'Breaker 20A', 'Breakers'))->assertSessionHasNoErrors();
    $product = Product::sole();

    skuAs($this)->put("{$this->url}/inventory/products/{$product->id}", skuProduct($this, 'Breaker 20A', 'Lighting', ['sku' => 'LGT-999999']))->assertSessionHasNoErrors();

    expect($product->fresh())->sku->toBe('BRK-000001')->category->toBe('Lighting');
});

it('never reuses a number already taken, including archived products and SKUs typed in imports', function () {
    $taken = Product::create(['team_id' => $this->team->id, 'sku' => 'BRK-000007', 'name' => 'Old breaker', 'category' => 'Breakers', 'price' => 1, 'stock' => 0, 'is_active' => true]);
    $taken->delete(); // archived

    $generator = app(SkuGenerator::class);
    expect($generator->peek($this->team->id, 'Breakers'))->toBe('BRK-000008')
        ->and($generator->next($this->team->id, 'Breakers'))->toBe('BRK-000008')
        ->and($generator->next($this->team->id, 'Breakers'))->toBe('BRK-000009');

    // Every call reserves its own number, even if the first product was never saved.
    $other = Team::factory()->create();
    expect($generator->next($other->id, 'Breakers'))->toBe('BRK-000001'); // per team
});

it('gives simultaneous requests different numbers', function () {
    // Many products created back to back in separate transactions, as concurrent requests would:
    // each one takes the next number from the locked sequence row.
    $skus = collect(range(1, 25))->map(fn () => DB::transaction(fn () => app(SkuGenerator::class)->next($this->team->id, 'Lighting')));

    expect($skus->unique()->count())->toBe(25)->and($skus->last())->toBe('LGT-000025');
});

it('keeps a SKU from the import file and generates one from the category when it is missing', function () {
    // The file's own BRK-000002 is kept, and the generated Breakers SKU skips past it.
    $csv = "SKU,Product Name,Category,Unit,Selling Price\n"
        .",Breaker 40A,Breakers,pcs,500\n"
        ."BRK-000002,Breaker 60A,Breakers,pcs,700\n"
        ."MAN-123,Junction Box,General,pcs,35\n"
        .",Spare Part,,pcs,10\n";
    $file = UploadedFile::fake()->createWithContent('products.csv', $csv);
    $id = skuAs($this)->post("{$this->url}/imports/inventory", ['file' => $file])->assertCreated()->json('id');
    expect(ImportBatch::findOrFail($id)->status)->toBe(ImportBatch::READY);

    skuAs($this)->post("{$this->url}/imports/batches/{$id}/confirm")->assertOk()->assertJson(['created' => 4]);

    expect(Product::orderBy('name')->pluck('sku', 'name')->all())->toBe([
        'Breaker 40A' => 'BRK-000003',
        'Breaker 60A' => 'BRK-000002',
        'Junction Box' => 'MAN-123',
        'Spare Part' => 'GEN-000001',
    ]);
});
